function loadDB(){
 if(!fs.existsSync(DB_PATH)){const init={vendors:expandedVendors,bookings:[],users:[],sessions:[]};fs.writeFileSync(DB_PATH,JSON.stringify(init,null,2));return init;}
 try {const db=JSON.parse(fs.readFileSync(DB_PATH,"utf8"));let existing=db.vendors||[];const generatedById=new Map(expandedVendors.map(v=>[Number(v.id),v]));existing=existing.map(v=>{if(v.isDemo && Number(v.id)>8 && generatedById.has(Number(v.id))) return {...generatedById.get(Number(v.id)),id:v.id}; return v;});const names=new Set(existing.map(v=>String(v.name||"").toLowerCase()));let maxId=existing.reduce((m,v)=>Math.max(m,Number(v.id)||0),0);const additions=expandedVendors.filter(v=>!names.has(String(v.name||"").toLowerCase())).map(v=>({...v,id:++maxId}));return {vendors:[...existing,...additions],bookings:db.bookings||[],users:db.users||[],sessions:db.sessions||[]};}
 catch {return {vendors:expandedVendors,bookings:[],users:[],sessions:[]};}
}
let db=loadDB();
function save(){fs.writeFileSync(DB_PATH,JSON.stringify(db,null,2));}
function nextId(rows){return rows.reduce((m,x)=>Math.max(m,Number(x.id)||0),0)+1;}
function safeUser(u){const {passwordHash,...rest}=u;return rest;}
function hashPassword(password,salt=crypto.randomBytes(16).toString("hex")){const hash=crypto.scryptSync(password,salt,64).toString("hex");return `${salt}:${hash}`;}
function verifyPassword(password,stored){try{if(!stored||!stored.includes(":"))return false;const [salt,old]=stored.split(":");const expected=Buffer.from(old,"hex");const actual=crypto.scryptSync(password,salt,64);return expected.length===actual.length&&crypto.timingSafeEqual(expected,actual);}catch{return false;}}
// Read a local .env file without adding another package. Never commit real credentials.
const envPath=path.join(__dirname,".env");
if(fs.existsSync(envPath)) for(const line of fs.readFileSync(envPath,"utf8").split(/\r?\n/)){const m=line.match(/^\s*([A-Z0-9_]+)\s*=\s*(.*?)\s*$/);if(m&&!process.env[m[1]])process.env[m[1]]=m[2].replace(/^['"]|['"]$/g,"");}
function issueSession(user){const token=crypto.randomBytes(32).toString("hex");db.sessions=(db.sessions||[]).filter(s=>new Date(s.expiresAt)>new Date());db.sessions.push({token,userId:user.id,role:user.role,email:user.email,expiresAt:new Date(Date.now()+7*24*60*60*1000).toISOString()});save();return token;}
function auth(requiredRoles=[]){return (req,res,next)=>{const token=String(req.headers.authorization||"").replace(/^Bearer\s+/i,"");const session=(db.sessions||[]).find(s=>s.token===token&&new Date(s.expiresAt)>new Date());if(!session)return res.status(401).json({error:"Please log in to continue."});const user=db.users.find(u=>u.id===session.userId);if(!user&&session.role!=="admin")return res.status(401).json({error:"Account no longer exists. Please log in again."});req.auth={...session,user:user||{id:0,name:"Administrator",email:session.email,role:"admin"}};if(requiredRoles.length&&!requiredRoles.includes(req.auth.role))return res.status(403).json({error:"You do not have permission to perform this action."});next();};}
function isVendorOwner(v,user){return String(v.contact||"").toLowerCase()===String(user.email||"").toLowerCase();}

app.get("/api/health",(req,res)=>res.json({ok:true,app:"Wedora API",database:"JSON file",time:new Date().toISOString()}));
app.get("/api/vendors",(req,res)=>{let list=[...db.vendors];const {city,cat,q,verified}=req.query;if(city)list=list.filter(v=>(v.city||"").toLowerCase()===String(city).toLowerCase()||(v.area||"").toLowerCase().includes(String(city).toLowerCase()));if(cat&&cat!=="All Services")list=list.filter(v=>(v.cat||"").toLowerCase()===String(cat).toLowerCase());if(q){const s=String(q).toLowerCase();list=list.filter(v=>[v.name,v.cat,v.city,v.area,v.description].join(" ").toLowerCase().includes(s));}if(verified==="true")list=list.filter(v=>v.verified);res.json(list);});
app.get("/api/vendors/:id",(req,res)=>{const v=db.vendors.find(x=>x.id===Number(req.params.id));if(!v)return res.status(404).json({error:"Vendor not found"});res.json(v);});
app.post("/api/vendors",auth(["vendor","admin"]),(req,res)=>{const {name,cat,area,city,state,price,img,image,description,contact,registrationNo,phone,website,yearsExperience,capacity}=req.body||{};if(!name||!cat||!city||!area||!price)return res.status(400).json({error:"Business name, category, price, city and area are required."});if(image&&(!/^data:image\/(png|jpeg|webp);base64,/i.test(image)||image.length>3_000_000))return res.status(400).json({error:"Please upload a PNG, JPEG or WebP image smaller than 2 MB."});const owner=req.auth.role==="vendor"?req.auth.user.email:String(contact||req.auth.user.email);const v={id:nextId(db.vendors),name:String(name).trim(),cat,area,city,state:state||"",price:price||"Contact for price",rating:0,distance:"Ask vendor",img:image||img||uniqueImage(cat,nextId(db.vendors)),image:image||"",description:description||"",contact:owner,registrationNo:registrationNo||"",phone:phone||"",website:website||"",yearsExperience:Number(yearsExperience)||0,capacity:Number(capacity)||0,verified:false,isDemo:false,createdAt:new Date().toISOString()};db.vendors.push(v);save();res.status(201).json(v);});
app.put("/api/vendors/:id",auth(["vendor","admin"]),(req,res)=>{const v=db.vendors.find(x=>x.id===Number(req.params.id));if(!v)return res.status(404).json({error:"Vendor not found"});if(req.auth.role==="vendor"&&!isVendorOwner(v,req.auth.user))return res.status(403).json({error:"You can only edit your own vendor listing."});for(const k of ["name","cat","area","city","state","price","img","description","registrationNo","phone","website","yearsExperience","capacity"])if(req.body[k]!==undefined)v[k]=req.body[k];if(req.auth.role==="admin"&&req.body.contact!==undefined)v.contact=String(req.body.contact).trim().toLowerCase();if(req.body.image!==undefined){if(req.body.image&&!/^data:image\/(png|jpeg|webp);base64,/i.test(req.body.image))return res.status(400).json({error:"Unsupported image format."});v.image=req.body.image;v.img=req.body.image||v.img;}if(req.auth.role==="admin"&&req.body.verified!==undefined)v.verified=Boolean(req.body.verified);save();res.json(v);});
app.delete("/api/vendors/:id",auth(["admin"]),(req,res)=>{const n=db.vendors.length;db.vendors=db.vendors.filter(x=>x.id!==Number(req.params.id));if(n===db.vendors.length)return res.status(404).json({error:"Vendor not found"});save();res.json({ok:true});});

app.post("/api/auth/register",(req,res)=>{const {name,email,password,role="customer"}=req.body||{};if(!name||!email||!password)return res.status(400).json({error:"Name, email and password are required."});if(!/^\S+@\S+\.\S+$/.test(String(email)))return res.status(400).json({error:"Enter an email-shaped address (it does not need inbox verification for local demo use)."});if(String(password).length<6)return res.status(400).json({error:"Password must be at least 6 characters."});if(!["customer","vendor"].includes(role))return res.status(400).json({error:"Admin accounts cannot be registered here. Configure the admin in .env."});if(db.users.some(u=>u.email.toLowerCase()===String(email).toLowerCase()))return res.status(409).json({error:"An account with this email already exists."});const user={id:nextId(db.users),name:String(name).trim(),email:String(email).trim().toLowerCase(),role,passwordHash:hashPassword(String(password)),createdAt:new Date().toISOString()};db.users.push(user);save();res.status(201).json({user:safeUser(user),message:"Account created. Please log in."});});
app.post("/api/auth/login",(req,res)=>{const {email,password,role="customer"}=req.body||{};const cleanEmail=String(email||"").trim().toLowerCase();if(role==="admin"){const adminEmail=String(process.env.ADMIN_EMAIL||"").trim().toLowerCase();const adminPassword=String(process.env.ADMIN_PASSWORD||"");if(!adminEmail||!adminPassword)return res.status(503).json({error:"Admin login is not configured yet. Copy .env.example to .env and set ADMIN_EMAIL and ADMIN_PASSWORD."});const emailOk=cleanEmail===adminEmail;const passOk=String(password||"")===adminPassword;if(!emailOk||!passOk)return res.status(401).json({error:"Invalid admin email or password."});const user={id:0,name:"Administrator",email:adminEmail,role:"admin"};const token=issueSession(user);return res.json({user,token,message:"Admin login successful."});}const user=db.users.find(u=>u.email===cleanEmail);if(!user||!verifyPassword(String(password||""),user.passwordHash))return res.status(401).json({error:"Invalid email or password."});if(role!==user.role)return res.status(403).json({error:`This account is registered as ${user.role}. Choose the matching login type.`});const token=issueSession(user);res.json({user:safeUser(user),token,message:"Login successful."});});
app.get("/api/auth/me",auth(),(req,res)=>res.json({user:req.auth.user}));
app.post("/api/auth/logout",auth(),(req,res)=>{db.sessions=(db.sessions||[]).filter(s=>s.token!==req.auth.token);save();res.json({ok:true});});
app.post("/api/bookings",auth(["customer"]),(req,res)=>{const {vendorId,customerName,email,phone,eventDate,guestCount,budget,message}=req.body||{};const vendor=db.vendors.find(v=>v.id===Number(vendorId));if(!vendor)return res.status(404).json({error:"Please select a valid vendor."});if(vendor.contact&&vendor.contact===req.auth.user.email)return res.status(400).json({error:"You cannot book your own listing."});if(!eventDate)return res.status(400).json({error:"Event date is required."});const b={id:nextId(db.bookings),vendorId:vendor.id,vendorName:vendor.name,customerName:String(customerName||req.auth.user.name).trim(),email:req.auth.user.email,phone:phone||"",eventDate,guestCount:Number(guestCount)||0,budget:Number(budget)||0,message:message||"",status:"Pending",createdAt:new Date().toISOString()};db.bookings.push(b);save();res.status(201).json({booking:b,message:"Booking request sent to vendor."});});
app.get("/api/bookings",auth(),(req,res)=>{let list=[...db.bookings];if(req.auth.role==="customer")list=list.filter(b=>b.email===req.auth.user.email);else if(req.auth.role==="vendor")list=list.filter(b=>db.vendors.some(v=>v.id===b.vendorId&&isVendorOwner(v,req.auth.user)));res.json(list.sort((a,b)=>b.id-a.id));});
app.patch("/api/bookings/:id",auth(["vendor","admin"]),(req,res)=>{const b=db.bookings.find(x=>x.id===Number(req.params.id));if(!b)return res.status(404).json({error:"Booking not found."});if(req.auth.role==="vendor"&&!db.vendors.some(v=>v.id===b.vendorId&&isVendorOwner(v,req.auth.user)))return res.status(403).json({error:"You can only manage requests for your own listings."});if(!["Pending","Accepted","Rejected","Completed"].includes(req.body.status))return res.status(400).json({error:"Invalid status."});b.status=req.body.status;save();res.json(b);});
app.get("/api/dashboard/summary",auth(["admin"]),(req,res)=>res.json({vendors:db.vendors.length,verifiedVendors:db.vendors.filter(v=>v.verified).length,unverifiedVendors:db.vendors.filter(v=>!v.verified).length,bookings:db.bookings.length,pendingBookings:db.bookings.filter(b=>b.status==="Pending").length,acceptedBookings:db.bookings.filter(b=>b.status==="Accepted").length,rejectedBookings:db.bookings.filter(b=>b.status==="Rejected").length,completedBookings:db.bookings.filter(b=>b.status==="Completed").length,users:db.users.length}));
app.get("/api/dashboard/customer",auth(["customer"]),(req,res)=>res.json({bookings:db.bookings.filter(b=>b.email===req.auth.user.email),savedVendors:[]}));
app.get("/api/dashboard/vendor",auth(["vendor"]),(req,res)=>res.json({vendors:db.vendors.filter(v=>isVendorOwner(v,req.auth.user)),bookings:db.bookings.filter(b=>db.vendors.some(v=>v.id===b.vendorId&&isVendorOwner(v,req.auth.user)))}));
app.use(express.static(path.join(__dirname,"dist")));
app.get("*",(req,res)=>{const index=path.join(__dirname,"dist","index.html");if(fs.existsSync(index))res.sendFile(index);else res.status(200).send("Wedora API is running. Start the frontend using npm run dev.");});
app.listen(PORT,()=>console.log(`Wedora server running at http://localhost:${PORT}`));
